Scan the grid and use iterative DFS to count each island, considering only orthogonal neighbors. Mark cells visited when pushing them so each is counted once; the input remains unchanged.

```javascript
function solve(grid) {
  const rows = grid.length;
  if (rows === 0) return 0;
  const cols = grid[0].length;
  if (cols === 0) return 0;

  const visited = Array.from({ length: rows }, () =>
    new Uint8Array(cols)
  );
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  let largest = 0;

  for (let row = 0; row < rows; row++) {
    for (let col = 0; col < cols; col++) {
      if (grid[row][col] !== 1 || visited[row][col]) continue;

      const stack = [[row, col]];
      visited[row][col] = 1;
      let area = 0;

      while (stack.length > 0) {
        const [r, c] = stack.pop();
        area++;

        for (const [dr, dc] of directions) {
          const nr = r + dr;
          const nc = c + dc;
          if (
            nr >= 0 && nr < rows &&
            nc >= 0 && nc < cols &&
            grid[nr][nc] === 1 && !visited[nr][nc]
          ) {
            visited[nr][nc] = 1;
            stack.push([nr, nc]);
          }
        }
      }

      largest = Math.max(largest, area);
    }
  }

  return largest;
}
```

Time: O(rows × cols). Auxiliary space: O(rows × cols). Call `solve(grid)` directly with a binary matrix; no imports, exports, or stdin/stdout handling.

