    while (true) {
      const left = index * 2 + 1;
      const right = left + 1;
      let smallest = index;

      if (left < heap.length &&
          heap[left].value < heap[smallest].value) {
        smallest = left;
      }
      if (right < heap.length &&
          heap[right].value < heap[smallest].value) {
        smallest = right;
      }
      if (smallest === index) return;

      [heap[index], heap[smallest]] =
        [heap[smallest], heap[index]];
      index = smallest;
    }
  }

